68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    /**
74	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that
75	     * contains at least one dot, with no whitespace anywhere. Deliberately lenient — it accepts
76	     * ordinary addresses while rejecting clearly malformed ones such as {@code not-an-email}.
77	     */
78	    private static final Pattern EMAIL_PATTERN =
79	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
80	
81	    /**
82	     * Dedicated audit logger. On a successful create an audit line carrying the owner id, the
83	     * customerCode and the registrationDate is emitted through this logger.
84	     */
85	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
86	
87	    private final ClinicService clinicService;
88	
89	    private final OwnerMapper ownerMapper;
90	
91	    private final PetMapper petMapper;
92	
93	    private final VisitMapper visitMapper;
94	
95	    public OwnerRestControllerV1(ClinicService clinicService,
96	                                 OwnerMapper ownerMapper,
97	                                 PetMapper petMapper,
98	                                 VisitMapper visitMapper) {
99	        this.clinicService = clinicService;
100	        this.ownerMapper = ownerMapper;
101	        this.petMapper = petMapper;
102	        this.visitMapper = visitMapper;
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
108	        Collection<Owner> owners;
109	        if (lastName != null) {
110	            owners = this.clinicService.findOwnerByLastName(lastName);
111	        } else {
112	            owners = this.clinicService.findAllOwners();
113	        }
114	        if (owners.isEmpty()) {
115	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
116	        }
117	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
118	    }
119	
120	    /**
121	     * Rejects an owner payload that is missing or blank in any required field, listing the name of
122	     * each offending field so the caller receives a 400 with a populated {@code errors} array.
123	     */
124	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
125	        List<String> missing = new ArrayList<>();
126	        if (isBlank(ownerFieldsDto.getFirstName())) {
127	            missing.add("firstName");
128	        }
129	        if (isBlank(ownerFieldsDto.getLastName())) {
130	            missing.add("lastName");
131	        }
132	        if (isBlank(ownerFieldsDto.getAddress())) {
133	            missing.add("address");
134	        }
135	        if (isBlank(ownerFieldsDto.getCity())) {
136	            missing.add("city");
137	        }
138	        if (isBlank(ownerFieldsDto.getTelephone())) {
139	            missing.add("telephone");
140	        }
141	        if (!missing.isEmpty()) {
142	            throw new RequiredFieldsMissingException(missing);
143	        }
144	    }
145	
146	    private static boolean isBlank(String value) {
147	        return value == null || value.isBlank();
148	    }
149	
150	    /**
151	     * Normalizes an address on create: leading/trailing whitespace is trimmed, every run of internal
152	     * whitespace is collapsed to a single space, the value is upper-cased and common abbreviations are
153	     * expanded token-by-token ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The
154	     * normalized value is what gets stored, returned and used for every address comparison; a value
155	     * that is blank (or {@code null}) normalizes to the empty string so the required-field check
156	     * rejects it.
157	     *
158	     * @param address the raw address as supplied by the caller, may be {@code null}
159	     * @return the normalized address ({@code ""} when blank or {@code null})
160	     */
161	    private static String normalizeAddress(String address) {
162	        if (address == null) {
163	            return "";
164	        }
165	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
166	        if (collapsed.isEmpty()) {
167	            return "";
168	        }
169	        String[] tokens = collapsed.split(" ");
170	        StringBuilder sb = new StringBuilder(collapsed.length());
171	        for (int i = 0; i < tokens.length; i++) {
172	            String token = tokens[i];
173	            switch (token) {
174	                case "ST" -> token = "STREET";
175	                case "RD" -> token = "ROAD";
176	                case "AVE" -> token = "AVENUE";
177	                default -> { }
178	            }
179	            if (i > 0) {
180	                sb.append(' ');
181	            }
182	            sb.append(token);
183	        }
184	        return sb.toString();
185	    }
186	
187	    /**
188	     * Normalizes a telephone on create into E.164 form. Spaces, dashes and brackets are stripped.
189	     * A leading {@code +} and its country code are kept as given; otherwise the country code
190	     * {@code +61} is assumed and a single leading {@code 0} is dropped from the national digits.
191	     * The result must carry 8 to 15 digits after the {@code +}. Returns the E.164 string to be
192	     * stored and returned.
193	     *
194	     * @param telephone the raw telephone as supplied by the caller
195	     * @return the normalized E.164 telephone (a {@code +} followed by 8 to 15 digits)
196	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
197	     */
198	    private static String normalizeTelephone(String telephone) {
199	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
200	        String e164;
201	        if (cleaned.startsWith("+")) {
202	            e164 = "+" + cleaned.substring(1);
203	        } else {
204	            String national = cleaned;
205	            if (national.startsWith("0")) {
206	                national = national.substring(1);
207	            }
208	            e164 = "+61" + national;
209	        }
210	        String digits = e164.substring(1);
211	        if (!digits.matches("\\d{8,15}")) {
212	            throw new InvalidTelephoneException(
213	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
214	        }
215	        return e164;
216	    }
217	
218	    /**
219	     * Normalizes an optional email. An absent or blank email is left unset (returns {@code null});
220	     * a present value must be a syntactically valid address and is stored and returned lower-cased.
221	     *
222	     * @param email the raw email as supplied by the caller, may be {@code null}
223	     * @return the lower-cased email, or {@code null} when none was supplied
224	     * @throws InvalidEmailException if a value is present but is not a syntactically valid address
225	     */
226	    private static String normalizeEmail(String email) {
227	        if (email == null || email.isBlank()) {
228	            return null;
229	        }
230	        String trimmed = email.trim();
231	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
232	            throw new InvalidEmailException("Email must be a syntactically valid address");
233	        }
234	        return trimmed.toLowerCase(Locale.ROOT);
235	    }
236	
237	    /**
238	     * Rejects a create whose E.164 telephone is already used by any existing owner, so that
239	     * telephones stay unique across owners. Telephones are stored in E.164 form on create, so a
240	     * direct equality comparison of the E.164 values against the stored values is sufficient.
241	     *
242	     * @param normalizedTelephone the E.164 telephone of the owner being created
243	     * @throws DuplicateTelephoneException if another owner already uses this telephone
244	     */
245	    private void rejectDuplicateTelephone(String normalizedTelephone) {
246	        boolean inUse = this.clinicService.findAllOwners().stream()
247	            .anyMatch(existing -> normalizedTelephone.equals(existing.getTelephone()));
248	        if (inUse) {
249	            throw new DuplicateTelephoneException(
250	                "Telephone is already used by another owner");
251	        }
252	    }
253	
254	    /**
255	     * Rejects a create that would place the owner in a household already occupied by another owner,
256	     * i.e. one whose last name and address match the supplied values. The two fields are compared
257	     * case-insensitively after whitespace is collapsed (leading/trailing whitespace trimmed and each
258	     * run of internal whitespace reduced to a single space), so {@code '110 W.  Liberty St. '} and
259	     * {@code '110 w. liberty st.'} are treated as the same address. The caller may bypass this check
260	     * by setting {@code sharesHousehold} to {@code true}.
261	     *
262	     * @param lastName the last name of the owner being created
263	     * @param address the address of the owner being created
264	     * @throws DuplicateHouseholdException if another owner already shares this last name and address
265	     */
266	    private void rejectDuplicateHousehold(String lastName, String address) {
267	        String normalizedLastName = normalizeForHousehold(lastName);
268	        String normalizedAddress = normalizeForHousehold(address);
269	        boolean inHousehold = this.clinicService.findAllOwners().stream()
270	            .anyMatch(existing ->
271	                normalizedLastName.equals(normalizeForHousehold(existing.getLastName()))
272	                    && normalizedAddress.equals(normalizeForHousehold(existing.getAddress())));
273	        if (inHousehold) {
274	            throw new DuplicateHouseholdException(
275	                "An owner with the same last name and address already exists");
276	        }
277	    }
278	
279	    /**
280	     * Normalizes a value for household comparison by trimming, collapsing every run of whitespace to
281	     * a single space and lower-casing, so the comparison is case-insensitive with collapsed whitespace.
282	     *
283	     * @param value the raw value, may be {@code null}
284	     * @return the normalized value ({@code ""} when {@code value} is {@code null})
285	     */
286	    private static String normalizeForHousehold(String value) {
287	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
288	    }
289	
290	    /**
291	     * Derives the stable household identifier for an owner from the normalized last name and address.
292	     * The value is a deterministic function of those two fields (compared case-insensitively with
293	     * collapsed whitespace, exactly as {@link #rejectDuplicateHousehold}), so every owner in the same
294	     * household — including owners who knowingly join it via {@code sharesHousehold} — is assigned the
295	     * same identifier without any existing record having to be updated. Formatted {@code 'HH-<HEX12>'}
296	     * where {@code HEX12} is the upper-cased first twelve hex characters of the SHA-256 of the two
297	     * normalized fields.
298	     *
299	     * @param lastName the last name of the owner being created
300	     * @param address the address of the owner being created
301	     * @return the stable household identifier
302	     */
303	    private static String householdId(String lastName, String address) {
304	        String key = normalizeForHousehold(lastName) + "\n" + normalizeForHousehold(address);
305	        try {
306	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
307	            StringBuilder sb = new StringBuilder(digest.length * 2);
308	            for (byte b : digest) {
309	                sb.append(String.format("%02x", b));
310	            }
311	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
312	        } catch (NoSuchAlgorithmException e) {
313	            throw new IllegalStateException("SHA-256 not available", e);
314	        }
315	    }
316	
317	    /**
318	     * The maximum number of owners a single city may contain. A create whose city already holds this
319	     * many owners is rejected, so a city never grows beyond this capacity.
320	     */
321	    private static final int CITY_CAPACITY = 50;
322	
323	    /**
324	     * Rejects a create whose city already contains {@link #CITY_CAPACITY} or more owners, so no city
325	     * ever exceeds its capacity. Cities are compared case-insensitively with surrounding whitespace
326	     * trimmed, exactly as {@link #nextCustomerCode} counts a city's owners. The count reflects the
327	     * state before the new owner is persisted, so it excludes the owner being created.
328	     *
329	     * @param city the city of the owner being created
330	     * @throws CityAtCapacityException if the city already contains {@link #CITY_CAPACITY} owners
331	     */
332	    private void rejectCityAtCapacity(String city) {
333	        String normalizedCity = normalizeName(city);
334	        long ownersInCity = this.clinicService.findAllOwners().stream()
335	            .filter(existing -> normalizedCity.equals(normalizeName(existing.getCity())))
336	            .count();
337	        if (ownersInCity >= CITY_CAPACITY) {
338	            throw new CityAtCapacityException(
339	                "The city already contains the maximum number of owners");
340	        }
341	    }
342	
343	    /**
344	     * The maximum number of owners that may be created on a single day. A create made once this many
345	     * owners already carry today's {@code registrationDate} is rejected, so no more than this many
346	     * owners are registered per day.
347	     */
348	    private static final int DAILY_OWNER_LIMIT = 100;
349	
350	    /**
351	     * Rejects a create once {@link #DAILY_OWNER_LIMIT} or more owners have already been created for
352	     * the given business day, counted by {@code registrationDate} equal to the effective (weekend
353	     * rolled forward) registration date of the owner being created. The count reflects the state
354	     * before the new owner is persisted, so it excludes the owner being created.
355	     *
356	     * @param registrationDate the effective business-day registration date of the owner being created
357	     * @throws DailyOwnerLimitExceededException if the day already holds {@link #DAILY_OWNER_LIMIT} owners
358	     */
359	    private void rejectDailyOwnerLimit(LocalDate registrationDate) {
360	        long ownersToday = this.clinicService.findAllOwners().stream()
361	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
362	            .count();
363	        if (ownersToday >= DAILY_OWNER_LIMIT) {
364	            throw new DailyOwnerLimitExceededException(
365	                "The maximum number of owners for today has already been reached");
366	        }
367	    }
368	
369	    /**
370	     * Rolls a registration date forward to a business day: a Saturday or Sunday is advanced to the
371	     * following Monday, any weekday is returned unchanged.
372	     *
373	     * @param date the effective registration date, supplied or defaulted to the server date
374	     * @return the same date when it is a weekday, otherwise the next Monday
375	     */
376	    private static LocalDate toBusinessDay(LocalDate date) {
377	        DayOfWeek dayOfWeek = date.getDayOfWeek();
378	        if (dayOfWeek == DayOfWeek.SATURDAY) {
379	            return date.plusDays(2);
380	        }
381	        if (dayOfWeek == DayOfWeek.SUNDAY) {
382	            return date.plusDays(1);
383	        }
384	        return date;
385	    }
386	
387	    /**
388	     * Builds the customer code assigned to an owner on create, formatted
389	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where {@code CITY3} is the upper-cased first three letters
390	     * of the owner's city, {@code LAST3} is the upper-cased first three letters of the owner's last
391	     * name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the
392	     * current number of owners already in that city, e.g. {@code 'MEL-SMI-0007'}.
393	     *
394	     * @param city the city of the owner being created
395	     * @param lastName the last name of the owner being created
396	     * @return the formatted customer code
397	     */
398	    private String nextCustomerCode(String city, String lastName) {
399	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
400	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
401	        String normalizedCity = normalizeName(city);
402	        int sequence = (int) this.clinicService.findAllOwners().stream()
403	            .filter(existing -> normalizedCity.equals(normalizeName(existing.getCity())))
404	            .count() + 1;
405	        return String.format("%s-%s-%04d", city3, last3, sequence);
406	    }
407	
408	    /**
409	     * Counts the existing owners that share the owner-to-be's first and last name, compared
410	     * case-insensitively (surrounding whitespace trimmed). The count reflects the state before the
411	     * new owner is persisted, so it excludes the owner being created.
412	     *
413	     * @param firstName the first name of the owner being created
414	     * @param lastName the last name of the owner being created
415	     * @return the number of existing owners with the same first and last name
416	     */
417	    private int countNamesakes(String firstName, String lastName) {
418	        String normalizedFirstName = normalizeName(firstName);
419	        String normalizedLastName = normalizeName(lastName);
420	        return (int) this.clinicService.findAllOwners().stream()
421	            .filter(existing ->
422	                normalizedFirstName.equals(normalizeName(existing.getFirstName()))
423	                    && normalizedLastName.equals(normalizeName(existing.getLastName())))
424	            .count();
425	    }
426	
427	    /**
428	     * Normalizes a name for case-insensitive comparison by trimming surrounding whitespace and
429	     * lower-casing.
430	     *
431	     * @param value the raw name, may be {@code null}
432	     * @return the normalized name ({@code ""} when {@code value} is {@code null})
433	     */
434	    private static String normalizeName(String value) {
435	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
436	    }
437	
438	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
439	    @Override
440	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
441	        Owner owner = this.clinicService.findOwnerById(ownerId);
442	        if (owner == null) {
443	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
444	        }
445	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
446	    }
447	
448	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
449	    @Override
450	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
451	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
452	        validateRequiredFields(ownerFieldsDto);
453	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
454	        if (registrationDate == null) {
455	            registrationDate = LocalDate.now();
456	        }
457	        registrationDate = toBusinessDay(registrationDate);
458	        ownerFieldsDto.setRegistrationDate(registrationDate);
459	        rejectDailyOwnerLimit(registrationDate);
460	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
461	            rejectDuplicateHousehold(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
462	        }
463	        rejectCityAtCapacity(ownerFieldsDto.getCity());
464	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
465	        rejectDuplicateTelephone(normalizedTelephone);
466	        ownerFieldsDto.setTelephone(normalizedTelephone);
467	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
468	        HttpHeaders headers = new HttpHeaders();
469	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
470	        owner.setCustomerCode(nextCustomerCode(ownerFieldsDto.getCity(), ownerFieldsDto.getLastName()));
471	        owner.setHouseholdId(householdId(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress()));
472	        owner.setNamesakeCount(countNamesakes(ownerFieldsDto.getFirstName(), ownerFieldsDto.getLastName()));
473	        this.clinicService.saveOwner(owner);
474	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
475	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
476	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
477	        headers.setLocation(UriComponentsBuilder.newInstance()
478	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
479	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
480	    }
481	
482	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
483	    @Override
484	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
485	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
486	        if (currentOwner == null) {
487	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
488	        }
489	        currentOwner.setAddress(ownerFieldsDto.getAddress());
490	        currentOwner.setCity(ownerFieldsDto.getCity());
491	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
492	        currentOwner.setLastName(ownerFieldsDto.getLastName());
493	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
494	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
495	        this.clinicService.saveOwner(currentOwner);
496	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
497	    }
