499	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
500	    @Transactional
501	    @Override
502	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
503	        Owner owner = this.clinicService.findOwnerById(ownerId);
504	        if (owner == null) {
505	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
506	        }
507	        this.clinicService.deleteOwner(owner);
508	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
509	    }
