511	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
512	    @Override
513	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
514	        Owner owner = this.clinicService.findOwnerById(ownerId);
515	        if (owner == null) {
516	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
517	        }
518	        HttpHeaders headers = new HttpHeaders();
519	        Pet pet = petMapper.toPet(petFieldsDto);
520	        owner.setId(ownerId);
521	        pet.setOwner(owner);
522	        pet.getType().setName(null);
523	        this.clinicService.savePet(pet);
524	        PetDto petDto = petMapper.toPetDto(pet);
525	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
526	            .buildAndExpand(pet.getId()).toUri());
527	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
528	    }
